<?php

declare(strict_types=1);

namespace Tests\Unit\Services\Schedule;

use Mfonte\Arkhive\Services\Schedule\CronTable;
use Mfonte\Arkhive\Services\Schedule\Schedule;
use PHPUnit\Framework\TestCase;
use Tests\Support\TempDir;

final class CronTableTest extends TestCase
{
    use TempDir;

    public function testRootGetsCronDLinesWithTheUserField(): void
    {
        self::assertSame(
            "# Generated by arkhive schedule for /etc/arkhive/config\n"
            . "# Save as /etc/cron.d/arkhive (root:root, mode 0644). Logs: /var/log/arkhive.log\n"
            . "PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\n"
            . "30 2 * * * root nice -n 10 /usr/local/bin/arkhive backup --config /etc/arkhive/config --log-file /var/log/arkhive.log >/dev/null 2>&1\n"
            . "30 5 * * 0 root nice -n 10 /usr/local/bin/arkhive maintain --config /etc/arkhive/config --log-file /var/log/arkhive.log >/dev/null 2>&1\n"
            . "30 5 * * 3 root nice -n 10 /usr/local/bin/arkhive drill --config /etc/arkhive/config --log-file /var/log/arkhive.log >/dev/null 2>&1\n",
            CronTable::render(new Schedule(['/usr/local/bin/arkhive'], '/etc/arkhive/config', 'root', 2, 30, '/var/log/arkhive.log')),
        );
    }

    public function testAnotherUserGetsCrontabLinesWithoutTheUserField(): void
    {
        $table = CronTable::render(new Schedule(['/usr/bin/php8.4', '/home/deploy/bin/arkhive.phar'], '/home/deploy/.config/arkhive/config', 'deploy', 23, 0, '/home/deploy/.local/state/arkhive/arkhive.log'));

        self::assertStringContainsString("# Add to the crontab of deploy with: crontab -e. Logs: /home/deploy/.local/state/arkhive/arkhive.log\n", $table);
        self::assertStringContainsString("0 23 * * * nice -n 10 /usr/bin/php8.4 /home/deploy/bin/arkhive.phar backup --config /home/deploy/.config/arkhive/config --log-file /home/deploy/.local/state/arkhive/arkhive.log >/dev/null 2>&1\n", $table);
        self::assertStringContainsString('0 2 * * 0 nice -n 10 /usr/bin/php8.4 /home/deploy/bin/arkhive.phar maintain ', $table);
        self::assertStringContainsString('0 2 * * 3 nice -n 10 /usr/bin/php8.4 /home/deploy/bin/arkhive.phar drill ', $table);
        self::assertStringNotContainsString(' root ', $table);
    }

    /**
     * The command field as cron runs it (\% back to %, then /bin/sh) gives the exact arguments.
     */
    public function testAwkwardPathsReachTheCommandIntact(): void
    {
        $dir = $this->tempDir();
        $recorder = "{$dir}/rec order's";
        mkdir($recorder);
        file_put_contents("{$recorder}/arkhive", "#!/bin/sh\nfor a in \"\$@\"; do printf '%s\\n' \"\$a\"; done\n");
        chmod("{$recorder}/arkhive", 0755);
        $config = "{$dir}/my conf/100% \"sure\" \$HOME `x` \\n";
        $table = CronTable::render(new Schedule(["{$recorder}/arkhive"], $config, 'deploy', 2, 30, "{$dir}/log %d.log"));

        $line = explode("\n", $table)[3];
        self::assertStringStartsWith('30 2 * * * nice -n 10 ', $line);
        self::assertStringNotContainsString('%', str_replace('\%', '', $line), 'every % is escaped for cron');
        $command = str_replace('\%', '%', substr($line, strlen('30 2 * * * nice -n 10 ')));
        $process = proc_open(['/bin/sh', '-c', $command], [1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes);
        self::assertIsResource($process);
        self::assertSame('', stream_get_contents($pipes[1]) . stream_get_contents($pipes[2]), 'the line itself prints nothing');
        fclose($pipes[1]);
        fclose($pipes[2]);
        self::assertSame(0, proc_close($process));
        // the output is redirected to /dev/null by the line itself: run it again without the redirection
        $process = proc_open(['/bin/sh', '-c', substr($command, 0, -strlen(' >/dev/null 2>&1'))], [1 => ['pipe', 'w']], $pipes);
        self::assertIsResource($process);
        $stdout = (string) stream_get_contents($pipes[1]);
        fclose($pipes[1]);
        proc_close($process);

        self::assertSame(['backup', '--config', $config, '--log-file', "{$dir}/log %d.log", ''], explode("\n", $stdout));
    }
}
